<?php

declare(strict_types=1);

namespace AbmmHasan\Benchmark;

use JsonException;

/** Generates a Bootstrap-powered browser dashboard for one archived benchmark run. */
final class BenchmarkDashboard
{
    /** @param array<string, mixed> $payload */
    public static function render(array $payload): string
    {
        try {
            $json = json_encode(
                $payload,
                JSON_THROW_ON_ERROR
                | JSON_UNESCAPED_SLASHES
                | JSON_HEX_TAG
                | JSON_HEX_AMP
                | JSON_HEX_APOS
                | JSON_HEX_QUOT,
            );
        } catch (JsonException) {
            $json = '{}';
        }

        return str_replace('__BENCHMARK_DATA__', $json, <<<'HTML'
